catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') return;

    var dateNeeded = g_form.getValue('date_needed');
    var dateToReturn = g_form.getValue('date_to_return_the_vehicle');

    // Only validate when both are populated
    if (dateNeeded && dateToReturn) {
        var needed = new Date(dateNeeded);
        var toReturn = new Date(dateToReturn);

        if (toReturn < needed) {
            // 1) Form-level message at the top (hard to miss)
            g_form.addErrorMessage('Date to return should not be before the Date needed');

            // 2) Field-level message, with scroll-to = true
            g_form.showFieldMsg(
                'date_to_return_the_vehicle',
                'Date to return should not be before the Date needed',
                'error',
                true // scroll to the field
            );

            // Clear after showing messages
            g_form.setValue('date_to_return_the_vehicle', '');

            // Prevent flicker: stop here so we don't immediately re-run onChange
            return;
        } else {
            // Clean up any earlier messages
            g_form.hideFieldMsg('date_to_return_the_vehicle', true);
            // Optional: clear form-level messages when valid
            g_form.clearMessages(); // clears addInfo/addError messages
        }
    }
}
